/*
  @title        深夜酒馆（LAPLACE Chat 适配版）
  @description  深棕 + 米白、思源宋体、原套组 9 宫格花纹；按 LAPLACE 的 DOM 重写
  @author       鲸鲸 为 主人 改写
  @updated      November 11, 2026
  @version      0.2.0
  @thumbnail    
*/

/* =============================================================
   依赖：同目录下的 bar/ 文件夹（14 张 png，共 552 KB）
   上传时保持  danmaku.css 和 bar/  是同级关系，图片会按相对路径自动找到。

   用法：
   1. 整个文件夹传到任意 HTTPS 静态托管（GitHub Pages / Gitee Pages / Vercel / 阿里云 ESA）
   2. chat.laplace.live → 样式 → 远程模版 → 填 .../danmaku.css 直链
   3. 基准字号 28，打开「头像」和「用户名」
   4. 复制生成的 OBS 弹幕机链接，塞进 OBS 浏览器源
   ============================================================= */

@layer template {
  /* ---------- 调色板 ---------- */
  :root,
  .event {
    --sy-brown: #4a3527;
    --sy-brown-deep: #362518;
    --sy-cream: #f5ead4;
    --sy-cream-dim: #e6d7b8;
    --sy-ink: #3d2a23;
    --sy-font: 'Source Han Serif CN Heavy', 'Source Han Serif CN',
               '思源宋体', 'Songti SC', 'SimSun', serif;
  }

  body {
    background-color: rgba(0, 0, 0, 0);
  }

  .event {
    font-family: var(--sy-font);
    --event-font-family: var(--sy-font);
  }

  .event-list {
    -webkit-mask-image: none !important;
    mask-image: none !important;
  }

  /* ================= 名字条（全身份共用：米白底 + 深棕圆角边） ================= */
  .event--message:not(.event-show-as--sticky) .meta,
  .event--gift:not(.event-show-as--sticky) .meta {
    display: flex !important;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px !important;
    padding: 0 !important;
    background: none !important;
  }

  .event--message:not(.event-show-as--sticky) .username,
  .event--gift:not(.event-show-as--sticky) .username {
    display: block !important;
    background: none !important;
    color: var(--sy-ink) !important;
    border: 6px solid transparent;
    border-image: url('data:image/png;base64,') 12 fill / 6px stretch;
    padding: 0 12px !important;
    font-size: 21px !important;
    font-weight: 700 !important;
    line-height: 1.3 !important;
    letter-spacing: 0.02em;
    text-shadow: none !important;
  }

  .username-text {
    padding-left: 2px;
    padding-right: 2px;
  }

  /* ================= 头像 ================= */
  .event--message:not(.event-show-as--sticky) .meta .avatar--sender,
  .event--gift:not(.event-show-as--sticky) .meta .avatar--sender {
    position: absolute !important;
    left: 4px !important;
    top: 2px !important;
    width: 68px !important;
    height: 68px !important;
    border-radius: 50%;
    border: 0 !important;
    background-color: var(--sy-brown-deep);
    z-index: 10;
  }

  .event--message {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding-left: 84px !important;
    padding-top: 6px;
    padding-bottom: 10px;
    margin-bottom: 14px;
  }

  /* ================= 普通观众：深棕底、米白字 ================= */
  .event--message .message {
    position: relative;
    display: inline-block !important;
    background: none !important;
    color: var(--sy-cream) !important;
    border: 15px solid transparent;
    border-image: url('data:image/png;base64,') 25 fill / 15px stretch;
    padding: 0 6px !important;
    font-size: 26px !important;
    font-weight: 700;
    line-height: 1.35;
    word-break: break-all;
    text-shadow: none;
  }

  /* 纯表情不加框 */
  .event--message .message:has(> .emote-wrap:only-child) {
    border-image: none !important;
    border-color: transparent !important;
  }

  .emote-wrap {
    display: inline-block;
    vertical-align: middle;
    line-height: 0;
  }
  .emote {
    height: 2.6em !important;
    width: auto !important;
    object-fit: contain;
    vertical-align: middle;
  }

  /* ================= 舰长（guard-level--3）：米白底、深棕字 ================= */
  .event--message.guard-level--3 .message {
    color: var(--sy-ink) !important;
    border-width: 14px 8px 14px 9px;
    border-image: url('data:image/png;base64,') 28 16 28 19 fill / 14px 8px 14px 9px stretch;
    padding: 0 8px !important;
  }

  /* 右下角小酒杯 */
  .event--message.guard-level--3 .message::after {
    content: "";
    position: absolute;
    right: -76px;
    bottom: -10px;
    width: 69px;
    height: 85px;
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: right bottom;
    background-size: 69px 85px;
    pointer-events: none;
    z-index: 1;
  }

  /* 舰长头像外圈花纹 */
  .event--message.guard-level--3 .meta .avatar--sender::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 80px;
    height: 87px;
    transform: translate(-50%, -50%);
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    pointer-events: none;
    z-index: -1;
  }

  /* ================= 提督（guard-level--2）：头像在右、气泡右对齐 ================= */
  .event--message.guard-level--2 {
    flex-direction: row-reverse;
    align-items: flex-end;
    padding-left: 0 !important;
    padding-right: 84px !important;
  }

  .event--message.guard-level--2 .meta .avatar--sender {
    left: auto !important;
    right: 4px !important;
  }

  .event--message.guard-level--2 .meta {
    justify-content: flex-end;
  }

  .event--message.guard-level--2 .message {
    color: var(--sy-ink) !important;
    border-width: 12px 9px 12px 7px;
    border-image: url('data:image/png;base64,') 24 19 22 15 fill / 12px 9px 12px 7px stretch;
    padding: 0 8px !important;
    margin-left: 0 !important;
    margin-right: 2px;
  }

  /* 左下角小酒杯 */
  .event--message.guard-level--2 .message::after {
    content: "";
    position: absolute;
    left: -88px;
    bottom: -17px;
    width: 75px;
    height: 90px;
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: left bottom;
    background-size: 75px 90px;
    pointer-events: none;
    z-index: 1;
  }

  .event--message.guard-level--2 .meta .avatar--sender::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 82px;
    height: 80px;
    transform: translate(-50%, -50%);
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    pointer-events: none;
    z-index: -1;
  }

  /* ================= 总督（guard-level--1）：米白底 + 更厚的边 ================= */
  .event--message.guard-level--1 .message {
    color: var(--sy-ink) !important;
    border-width: 13px;
    border-image: url('data:image/png;base64,') 27 fill / 13px stretch;
    padding: 0 8px !important;
  }

  .event--message.guard-level--1 .message::after {
    content: "";
    position: absolute;
    right: -81px;
    bottom: -10px;
    width: 74px;
    height: 82px;
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: right bottom;
    background-size: 74px 82px;
    pointer-events: none;
    z-index: 1;
  }

  .event--message.guard-level--1 .meta .avatar--sender::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 89px;
    height: 92px;
    transform: translate(-50%, -50%);
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    pointer-events: none;
    z-index: -1;
  }

  /* 主播：名字条压成深棕 */
  .event--message.user-type--streamer .message {
    filter: brightness(1.08);
  }

  /* ================= 礼物 ================= */
  /* 小礼物：只留米白描边字 */
  .event--gift.event-size--normal,
  .event--gift.event-size--normal * {
    color: var(--sy-cream) !important;
    --text: var(--sy-cream) !important;
    text-shadow:
      -1px -1px var(--sy-brown), 0 -1px var(--sy-brown), 1px -1px var(--sy-brown),
      -1px 0 var(--sy-brown), 1px 0 var(--sy-brown),
      -1px 1px var(--sy-brown), 0 1px var(--sy-brown), 1px 1px var(--sy-brown) !important;
  }
  .event--gift.event-size--normal {
    padding-left: 4px !important;
  }

  /* 大礼物：深棕长条卡（同普通气泡花纹） */
  .event--gift.event-size--highlight:not(.event-show-as--sticky) {
    background: none !important;
    border: 15px solid transparent;
    border-image: url('data:image/png;base64,') 25 fill / 15px stretch;
    padding: 2px 8px !important;
    margin: 8px 0 !important;
  }
  .event--gift.event-size--highlight:not(.event-show-as--sticky) * {
    color: var(--sy-cream) !important;
    --text: var(--sy-cream) !important;
    font-family: var(--sy-font);
  }

  /* ================= 醒目留言（SC） ================= */
  .event {
    --event-superchat-top-bg-1: rgba(74, 53, 39, 0.97);
    --event-superchat-top-bg-2: rgba(74, 53, 39, 0.97);
    --event-superchat-top-bg-3: rgba(110, 82, 48, 0.97);
    --event-superchat-top-bg-4: rgba(126, 76, 46, 0.97);
    --event-superchat-top-bg-5: rgba(140, 58, 40, 0.97);
    --event-superchat-top-bg-6: rgba(160, 43, 33, 0.97);

    --event-superchat-bg: rgba(54, 37, 24, 0.95);
    --event-superchat-bg-1: rgba(74, 53, 39, 0.97);
    --event-superchat-bg-2: rgba(74, 53, 39, 0.97);
    --event-superchat-bg-3: rgba(110, 82, 48, 0.97);
    --event-superchat-bg-4: rgba(126, 76, 46, 0.97);
    --event-superchat-bg-5: rgba(140, 58, 40, 0.97);
    --event-superchat-bg-6: rgba(160, 43, 33, 0.97);
  }

  .event--superchat:not(.event-show-as--sticky) {
    position: relative;
    background: none !important;
    border: 15px solid transparent;
    border-image: url('data:image/png;base64,') 25 fill / 15px stretch;
    padding: 2px 10px !important;
    margin: 8px 0 !important;
    font-family: var(--sy-font);
  }

  .event--superchat:not(.event-show-as--sticky) .top,
  .event--superchat:not(.event-show-as--sticky) .message,
  .event--superchat:not(.event-show-as--sticky) .bottom {
    background: none !important;
    border: 0 !important;
    color: var(--sy-cream) !important;
  }

  /* 右下角啤酒杯 */
  .event--superchat:not(.event-show-as--sticky)::after {
    content: "";
    position: absolute;
    right: -104px;
    bottom: -20px;
    width: 96px;
    height: 88px;
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: right bottom;
    background-size: 96px 88px;
    pointer-events: none;
    z-index: 1;
  }

  /* ================= 上舰 / 系统提示 ================= */
  .event {
    --event-toast-text: var(--sy-ink);
    --event-toast-text-1: var(--sy-cream);
    --event-toast-text-2: var(--sy-cream);
    --event-toast-text-3: var(--sy-cream);

    --event-toast-bg-1: rgba(160, 43, 33, 0.95);
    --event-toast-bg-2: rgba(120, 76, 140, 0.95);
    --event-toast-bg-3: rgba(58, 78, 150, 0.95);
  }

  .event--toast:not(.event-show-as--sticky) {
    position: relative;
    background: none !important;
    border: 15px solid transparent;
    border-image: url('data:image/png;base64,') 25 fill / 15px stretch;
    padding: 2px 10px !important;
    margin: 8px 0 22px !important;
    overflow: visible;
  }
  .event--toast:not(.event-show-as--sticky) * {
    color: var(--sy-cream) !important;
    font-family: var(--sy-font);
  }

  /* 「再来一舰」手写横幅 */
  .event--toast:not(.event-show-as--sticky)::after {
    content: "";
    position: absolute;
    left: 10px;
    bottom: -40px;
    width: 333px;
    height: 121px;
    background-image: url('data:image/png;base64,');
    background-repeat: no-repeat;
    background-position: left bottom;
    background-size: 333px 121px;
    pointer-events: none;
    z-index: 1;
  }

  /* ================= 进场动画 ================= */
  @keyframes syIn {
    0%   { opacity: 0; transform: translateY(14px); }
    100% { opacity: 1; transform: translateY(0); }
  }
  .can-motion .event:nth-last-child(-n+2) {
    animation: syIn 0.45s ease-out;
  }
}
